# Generated by build.py from recipe.yml for recipe ftp-upload-and-fetch-over-http. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-anonymous', '--allow-uploads', 'ftp://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -T notes.txt ftp://127.0.0.1:8080/notes.txt --next http://127.0.0.1:8081/notes.txt } finally { Stop-Process $server0 }
